column13:
mod.web_layout.BackendLayouts.twoColumns {
    title = Two columns
    config.backend_layout {
        colCount = 3
        rowCount = 1
        rows.1.columns {
            1 {
                name = Content
                colPos = 0
                identifier = content
            }
            2 {
                name = Aside
                colPos = 5
                identifier = aside
            }
            3 {
                name = Without identifier
                colPos = 2
            }
        }
    }
}
mod.web_layout.BackendLayouts.numbered {
    title = Numbered
    config.backend_layout {
        colCount = 1
        rowCount = 1
        rows.1.columns.1 {
            name = First
            colPos = 0
            identifier = 0
        }
    }
}
